html:
{%- set fmt = frappe.utils.fmt_money -%}
{%- set bills = [] -%}{%- set totals = {} -%}
{%- for row in doc.items -%}
	{%- set b = row.bill or _("General Items") -%}
	{%- if b not in bills %}{% set _ = bills.append(b) %}{% set _ = totals.update({b: [0, 0]}) %}{% endif -%}
	{%- set _ = totals.update({b: [totals[b][0] + (row.amount or 0), totals[b][1] + (row.revised_amount or 0)]}) -%}
{%- endfor -%}
{% include "consms/templates/print/ipc_styles.html" %}
<div class="ipc">
	<h1>{{ _("Revised Bill of Quantities") }}</h1>
	<h2>{{ frappe.db.get_value("Project", doc.project, "project_name") or doc.project }}</h2>
	<table class="meta"><tr><td><b>{{ _("BOQ") }}:</b> {{ doc.name }}</td><td class="num"><b>{{ _("Revision") }}:</b> {{ doc.revisions | selectattr("status", "equalto", "Approved") | list | length }}</td></tr></table>
	<table class="grid small">
		<thead><tr>
			<th style="width:7%">{{ _("Item No") }}</th><th>{{ _("Description") }}</th><th style="width:5%">{{ _("Unit") }}</th>
			<th>{{ _("Original Qty") }}</th><th>{{ _("Variation") }}</th><th>{{ _("Revised Qty") }}</th><th>{{ _("Rate") }}</th><th>{{ _("Original Amount") }}</th><th>{{ _("Revised Amount") }}</th>
		</tr></thead>
		<tbody>
		{%- for b in bills %}
			<tr class="bill-row"><td colspan="9">{{ b }}</td></tr>
			{%- for row in doc.items if (row.bill or _("General Items")) == b %}
			<tr>
				<td>{{ row.item_no or "" }}</td><td>{{ row.description or "" }}</td><td>{{ row.uom or "" }}</td>
				<td class="num">{{ "{:,.2f}".format(row.original_qty or 0) }}</td>
				<td class="num">{{ "{:+,.2f}".format(row.variation_qty) if row.variation_qty else "" }}</td>
				<td class="num">{{ "{:,.2f}".format(row.revised_qty or 0) }}</td>
				<td class="num">{{ fmt(row.unit_rate, precision=2) }}</td>
				<td class="num">{{ fmt(row.amount, precision=2) }}</td><td class="num">{{ fmt(row.revised_amount, precision=2) }}</td>
			</tr>
			{%- endfor %}
			<tr class="total-row"><td colspan="7">{{ _("Total {0}").format(b) }}</td><td class="num">{{ fmt(totals[b][0], precision=2) }}</td><td class="num">{{ fmt(totals[b][1], precision=2) }}</td></tr>
		{%- endfor %}
			<tr class="grand"><td colspan="7">{{ _("Original Total / Revised Total") }}</td><td class="num">{{ fmt(doc.total_amount, precision=2) }}</td><td class="num">{{ fmt(doc.revised_total, precision=2) }}</td></tr>
		</tbody>
	</table>
	{% if doc.revisions %}
	<p style="margin-top:8px"><b>{{ _("Revisions") }}</b></p>
	<table class="grid small">
		<tr><th>#</th><th>{{ _("Variation Order") }}</th><th>{{ _("Client Instruction No.") }}</th><th>{{ _("Approved On") }}</th><th>{{ _("Change") }}</th><th>{{ _("Revised BOQ Total") }}</th><th>{{ _("Status") }}</th></tr>
		{%- for r in doc.revisions %}
		<tr><td>{{ r.revision_no }}</td><td>{{ r.variation_order }}</td><td>{{ r.client_instruction_no or "" }}</td><td>{{ frappe.utils.formatdate(r.approval_date) if r.approval_date else "" }}</td>
			<td class="num">{{ fmt(r.change_amount, precision=2) }}</td><td class="num">{{ fmt(r.revised_total, precision=2) }}</td><td>{{ r.status }}</td></tr>
		{%- endfor %}
	</table>
	{% endif %}
</div>
